You are working in /tmp/sv-9040afccc9924a49888d884be7a6c262/ShipmentTracker. This is a Blazor Web App with Auto interactivity (Server + WebAssembly) and Individual accounts authentication, using .NET 11 preview. The solution has two projects:
- ShipmentTracker (server) at ShipmentTracker/ShipmentTracker/
- ShipmentTracker.Client (WASM) at ShipmentTracker/ShipmentTracker.Client/

I need you to add shipment tracking functionality:

## 1. Create a shared Shipment model

Create file `ShipmentTracker/ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required]
    public string Origin { get; set; } = string.Empty;

    [Required]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; } = ShipmentStatus.Pending;

    public DateTime CreatedDate { get; set; } = DateTime.UtcNow;

    public DateTime? EstimatedDelivery { get; set; }

    public string? CustomerEmail { get; set; }

    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Exception
}
```

## 2. Create a shared DTO for the client project

Create file `ShipmentTracker/ShipmentTracker.Client/Models/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}
```

## 3. Update ApplicationDbContext to include Shipments

Edit `ShipmentTracker/ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
public DbSet<Shipment> Shipments => Set<Shipment>();
```

## 4. Add API endpoints for shipments

Edit `ShipmentTracker/ShipmentTracker/Program.cs` — before `app.Run();`, add minimal API endpoints:

```csharp
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    return shipments.Select(s => new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    });
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    if (shipment is null) return Results.NotFound();
    return Results.Ok(new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = shipment.Status.ToString(),
        CreatedDate = shipment.CreatedDate,
        EstimatedDelivery = shipment.EstimatedDelivery,
        CustomerEmail = shipment.CustomerEmail,
        Notes = shipment.Notes
    });
}).RequireAuthorization();

app.MapPost("/api/shipments", async (ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = new Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = Enum.Parse<ShipmentStatus>(dto.Status),
        CreatedDate = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        CustomerEmail = dto.CustomerEmail,
        Notes = dto.Notes
    };
    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();
    dto.Id = shipment.Id;
    dto.CreatedDate = shipment.CreatedDate;
    return Results.Created($"/api/shipments/{shipment.Id}", dto);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();
    shipment.TrackingNumber = dto.TrackingNumber;
    shipment.Origin = dto.Origin;
    shipment.Destination = dto.Destination;
    shipment.Status = Enum.Parse<ShipmentStatus>(dto.Status);
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.CustomerEmail = dto.CustomerEmail;
    shipment.Notes = dto.Notes;
    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization();
```

Also add `using ShipmentTracker.Data;` at the top if not already there, and add a `using Microsoft.EntityFrameworkCore;` if needed (check if already present).

