## 6. Create the Dispatcher page (client-side, interactive)

Create directory `ShipmentTracker/ShipmentTracker.Client/Pages/` if it doesn't exist, then create `ShipmentTracker/ShipmentTracker.Client/Pages/Shipments.razor`:

```razor
@page "/shipments"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@using System.Net.Http.Json
@attribute [Authorize]
@inject HttpClient Http
@rendermode InteractiveWebAssembly

<PageTitle>Shipments - Dispatcher View</PageTitle>

<h2>Shipment Dashboard</h2>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    <select class="form-select" style="max-width:200px" @bind="statusFilter">
        <option value="">All Statuses</option>
        <option value="Pending">Pending</option>
        <option value="PickedUp">Picked Up</option>
        <option value="InTransit">In Transit</option>
        <option value="OutForDelivery">Out for Delivery</option>
        <option value="Delivered">Delivered</option>
        <option value="Exception">Exception</option>
    </select>
    <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3 p-3">
        <h5>Create New Shipment</h5>
        <div class="row g-2">
            <div class="col-md-2">
                <input class="form-control" placeholder="Tracking #" @bind="newShipment.TrackingNumber" />
            </div>
            <div class="col-md-2">
                <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
            </div>
            <div class="col-md-2">
                <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
            </div>
            <div class="col-md-2">
                <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
            </div>
            <div class="col-md-2">
                <input type="date" class="form-control" @bind="estimatedDate" />
            </div>
            <div class="col-md-2">
                <button class="btn btn-success me-1" @onclick="CreateShipment">Save</button>
                <button class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments match the current filter.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><strong>@s.TrackingNumber</strong></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadge(s.Status)">@FormatStatus(s.Status)</span></td>
                    <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                    <td>@(s.CustomerEmail ?? "—")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                value="@s.Status" @onchange="(e) => UpdateStatus(s, e.Value?.ToString())">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Exception">Exception</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;
    private bool showCreateForm;
    private ShipmentDto newShipment = new() { Status = "Pending" };
    private DateTime estimatedDate = DateTime.Today.AddDays(5);

    private IEnumerable<ShipmentDto> FilteredShipments => shipments!
        .Where(s => string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
    }

    private void ShowCreateForm()
    {
        newShipment = new ShipmentDto { Status = "Pending" };
        estimatedDate = DateTime.Today.AddDays(5);
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDelivery = estimatedDate;
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showCreateForm = false;
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus) || shipment.Status == newStatus) return;
        shipment.Status = newStatus;
        await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
    }

    private string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };

    private string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };
}
```

## 7. Create the Customer Tracking page (client-side, interactive)

Create `ShipmentTracker/ShipmentTracker.Client/Pages/Track.razor`:

```razor
@page "/track"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@using System.Net.Http.Json
@attribute [Authorize]
@inject HttpClient Http
@rendermode InteractiveWebAssembly

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (errorMessage is not null)
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadge(shipment.Status) fs-6">@FormatStatus(shipment.Status)</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Origin:</strong> @shipment.Origin</p>
                    <p><strong>Destination:</strong> @shipment.Destination</p>
                    <p><strong>Shipped:</strong> @shipment.CreatedDate.ToString("MMMM dd, yyyy")</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Estimated Delivery:</strong>
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <span class="fw-bold text-primary">@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
