        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };

    private int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        "Exception" => 50,
        _ => 0
    };

    private string GetProgressBarClass(string status) => status switch
    {
        "Exception" => "bg-danger",
        "Delivered" => "bg-success",
        _ => "bg-primary"
    };
}
```

## 8. Register HttpClient in the client project

Edit `ShipmentTracker/ShipmentTracker.Client/Program.cs` to register an HttpClient. The file should look something like:

```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });

await builder.Build().RunAsync();
```

Make sure the HttpClient registration line is added if it doesn't exist already.

## 9. Update the navigation (NavMenu)

Find the NavMenu component (likely in `ShipmentTracker/ShipmentTracker/Components/Layout/NavMenu.razor`) and add navigation links for the new pages:

