using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();
    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-001", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "alice@example.com" },
            new Shipment { TrackingNumber = "TRK-002", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.PickedUp, EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "bob@example.com" },
            new Shipment { TrackingNumber = "TRK-003", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "carol@example.com" },
            new Shipment { TrackingNumber = "TRK-004", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "dave@example.com" },
            new Shipment { TrackingNumber = "TRK-005", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Exception, EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "eve@example.com", Notes = "Customs hold" }
        );
        db.SaveChanges();
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())

app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    return shipments.Select(s => new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    });
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    if (shipment is null) return Results.NotFound();
    return Results.Ok(new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = shipment.Status.ToString(),
        CreatedDate = shipment.CreatedDate,
        EstimatedDelivery = shipment.EstimatedDelivery,
        CustomerEmail = shipment.CustomerEmail,
        Notes = shipment.Notes
    });
}).RequireAuthorization();

app.MapPost("/api/shipments", async (ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = new Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = Enum.Parse<ShipmentStatus>(dto.Status),
        CreatedDate = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        CustomerEmail = dto.CustomerEmail,
        Notes = dto.Notes
    };
    db.Shipments.Add(shipment);
    await db.SaveChangesAsync();
    dto.Id = shipment.Id;
    dto.CreatedDate = shipment.CreatedDate;
    return Results.Created($"/api/shipments/{shipment.Id}", dto);
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}", async (int id, ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();
    shipment.TrackingNumber = dto.TrackingNumber;
    shipment.Origin = dto.Origin;
    shipment.Destination = dto.Destination;
    shipment.Status = Enum.Parse<ShipmentStatus>(dto.Status);
    shipment.EstimatedDelivery = dto.EstimatedDelivery;
    shipment.CustomerEmail = dto.CustomerEmail;
    shipment.Notes = dto.Notes;
    await db.SaveChangesAsync();
    return Results.NoContent();
}).RequireAuthorization();

app.Run();

